<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{Container,Csrf,Database,Request,Response,View};
use App\Repositories\AcademicOfferingRepository;
use App\Services\AccessService;
final class AcademicOfferingController{
 private function repo():AcademicOfferingRepository{return new AcademicOfferingRepository(Container::get(Database::class)->connection());}
 private function csrf(Request $r):void{if(!Csrf::validate((string)$r->input('_csrf')))Response::abort(419,'CSRF inválido.');}
 public function index(Request $r):void{AccessService::require('academico.oferta.ver');$x=$this->repo();View::render('admin/academico/oferta/index',['title'=>'Períodos y oferta académica','periods'=>$x->periods(),'offers'=>$x->offers()]);}
 public function periodForm(Request $r):void{AccessService::require('academico.oferta.gestionar');$x=$this->repo();$id=(int)$r->input('id');View::render('admin/academico/oferta/period-form',['title'=>$id?'Editar período académico':'Nuevo período académico','period'=>$id?$x->period($id):null,'types'=>$x->periodTypes(),'states'=>$x->periodStates()]);}
 public function periodSave(Request $r):never{$this->csrf($r);AccessService::require('academico.oferta.gestionar');$d=['id'=>(int)$r->input('id'),'type'=>(int)$r->input('tipo_periodo_id'),'state'=>(int)$r->input('estado_periodo_id'),'code'=>strtoupper(trim((string)$r->input('codigo'))),'name'=>trim((string)$r->input('nombre')),'start'=>(string)$r->input('fecha_inicio'),'end'=>(string)$r->input('fecha_fin'),'ms'=>(string)$r->input('fecha_inicio_matricula'),'me'=>(string)$r->input('fecha_fin_matricula'),'gs'=>(string)$r->input('fecha_inicio_calificaciones'),'ge'=>(string)$r->input('fecha_fin_calificaciones'),'active'=>$r->input('activo')!==null?1:0];if(!$d['state']||!$d['code']||!$d['name']||!$d['start']||!$d['end'])Response::abort(422,'Estado, código, nombre y fechas del período son obligatorios.');$this->repo()->savePeriod($d);Response::redirect('/admin/academico/oferta');}
 public function offerForm(Request $r):void{AccessService::require('academico.oferta.gestionar');$x=$this->repo();$id=(int)$r->input('id');View::render('admin/academico/oferta/offer-form',['title'=>$id?'Editar oferta académica':'Nueva oferta académica','offer'=>$id?$x->offer($id):null,'periods'=>$x->periods(),'states'=>$x->offerStates(),'careers'=>$x->careers(),'curricula'=>$x->curricula(),'campuses'=>$x->campuses(),'modalities'=>$x->modalities()]);}
 public function offerSave(Request $r):never{$this->csrf($r);AccessService::require('academico.oferta.gestionar');$d=['id'=>(int)$r->input('id'),'period'=>(int)$r->input('periodo_academico_id'),'career'=>(int)$r->input('carrera_id'),'curriculum'=>(int)$r->input('malla_id'),'campus'=>(int)$r->input('sede_id'),'modality'=>(int)$r->input('modalidad_academica_id'),'state'=>(int)$r->input('estado_oferta_id'),'code'=>strtoupper(trim((string)$r->input('codigo'))),'name'=>trim((string)$r->input('nombre')),'published'=>(string)$r->input('fecha_publicacion'),'active'=>$r->input('activo')!==null?1:0];if(!$d['period']||!$d['career']||!$d['curriculum']||!$d['state']||!$d['code']||!$d['name'])Response::abort(422,'Período, carrera, malla, estado, código y nombre son obligatorios.');$id=$this->repo()->saveOffer($d);Response::redirect('/admin/academico/oferta/ver?id='.$id);}
 public function show(Request $r):void{AccessService::require('academico.oferta.ver');$x=$this->repo();$id=(int)$r->input('id');$o=$x->offer($id);if(!$o)Response::abort(404,'Oferta académica no encontrada.');View::render('admin/academico/oferta/show',['title'=>'Oferta académica','offer'=>$o,'sections'=>$x->sections($id),'subjects'=>$x->curriculumSubjectsForOffer($id),'states'=>$x->sectionStates(),'parallels'=>$x->parallels()]);}
 public function sectionSave(Request $r):never{$this->csrf($r);AccessService::require('academico.oferta.gestionar');$d=['offer'=>(int)$r->input('oferta_academica_id'),'subject'=>(int)$r->input('malla_asignatura_id'),'parallel'=>(int)$r->input('paralelo_id'),'state'=>(int)$r->input('estado_seccion_id'),'code'=>strtoupper(trim((string)$r->input('codigo'))),'name'=>trim((string)$r->input('nombre')),'capacity'=>(int)$r->input('cupo_maximo'),'allow'=>$r->input('permite_matricula')!==null?1:0,'open'=>(string)$r->input('fecha_apertura'),'close'=>(string)$r->input('fecha_cierre')];if(!$d['offer']||!$d['subject']||!$d['state']||!$d['code']||!$d['name'])Response::abort(422,'Asignatura, estado, código y nombre de sección son obligatorios.');$this->repo()->saveSection($d);Response::redirect('/admin/academico/oferta/ver?id='.$d['offer']);}
}
